const r = $input.first().json;
const cal = r.body.Calendars[1];
return [{ json: { calendarid: cal.calendarid, calendar_name: cal.name, calendar_workstation: cal.workstation, problem_description: cal.problem_description } }];

const r = $input.first().json;
const rec = r.body.Records[0];
const slot = rec.free_timespace[0];
return [{ json: { wday: rec.wday, slot: slot.slot, slotid: slot.slotid } }];

const auth = $('Extract Token').item.json;
const cal = $('Extract Calendar').item.json;
const slot = $('Extract Slot').item.json;
const badResp = $('post_schedule.php (BAD desc)').item.json;
const goodResp = $('post_schedule.php (GOOD desc)').item.json;
const schedResp = $('get_schedule.php (verify)').item.json;
const schedPatientResp = $('get_schedule_patient.php (verify)').item.json;

const schedRecords = (schedResp.body || []);
const found = Array.isArray(schedRecords) ? schedRecords.find(r => r.phone === '0700000009') : undefined;

return [{ json: {
  step1_auth: { status: auth.auth_status, got_token: !!auth.token },
  step2_calendar_used: { name: cal.calendar_name, workstation: cal.calendar_workstation },
  step3_slot_used: { wday: slot.wday, slot: slot.slot },
  step4_post_schedule_bad_problemDescription: { status: badResp.statusCode, body: badResp.body },
  step5_post_schedule_valid_problemDescription: { status: goodResp.statusCode, body: goodResp.body },
  step6_get_schedule_lookup: { status: schedResp.statusCode, total_records_in_window: Array.isArray(schedRecords) ? schedRecords.length : null, found_our_test_booking: !!found },
  step7_get_schedule_patient_lookup: { status: schedPatientResp.statusCode, body: schedPatientResp.body },
  conclusion: found ? "Booking WAS found via get_schedule.php" : "Booking created (Result:OK) but NOT retrievable via get_schedule.php or get_schedule_patient.php - confirms the gap reported to Imreh."
}}];

const b = ($input.first().json.body) || {};
const str = x => (typeof x === 'string' ? x.trim() : '');
const tzDate = d => new Date(Date.now() + d * 86400000)
  .toLocaleDateString('en-CA', { timeZone: 'Europe/Bucharest' });
let date_from = str(b.date_from);
const today = tzDate(0);
const requested_date = (/^\d{4}-\d{2}-\d{2}$/.test(date_from) && date_from > today) ? date_from : '';
if (!requested_date) date_from = tzDate(1);
// Only these values survive; anything else (typo, null, "Doctor ", garbage) becomes '' which
// means "no filter" - and an unfiltered search now also EXCLUDES specialty calendars, so a garbled
// provider_type can never surface a specialty provider by accident.
// 'vision_therapy' (2026-09-16) is how the agent asks for psycho-orthoptic therapy / szemtorna.
// Separators are normalised so vision-therapy / "vision therapy" land on the same value.
const pt = str(b.provider_type).toLowerCase().replace(/[\s-]+/g, '_');
const KINDS = ['doctor', 'optometrist', 'vision_therapy'];
const provider_type = KINDS.includes(pt) ? pt : '';
return [{ json: { doctor: str(b.doctor), city: str(b.city), location: str(b.location),
  date_from, requested_date, provider_type } }];

const sd = $getWorkflowStaticData('global');
const now = Date.now();
if (sd.token && sd.tokenTs && (now - sd.tokenTs) < 45 * 60 * 1000) {
  return [{ json: { token: sd.token, needAuth: false } }];
}
return [{ json: { needAuth: true } }];

const r = $input.first().json;
if (r.statusCode !== 200 || !r.body || !r.body.token) {
  return [{ json: { _error: true, success: false, error: 'auth_failed', status: r.statusCode,
    hint: 'Could not authenticate to the clinic system. Tell the caller to try again shortly.' } }];
}
const sd = $getWorkflowStaticData('global');
sd.token = r.body.token;
sd.tokenTs = Date.now();
return [{ json: { token: sd.token } }];

const j = $input.first().json;
if (j._error) return [{ json: j }];
return [{ json: { token: j.token } }];

// ---- calendar name vs service (2026-09-16) ----
// One calendar of 30 carries its service in its NAME: "Dr. Prof. Szekely Attila  - Consiliere /
// Terapie psiho-ortoptica" (note the double space). Returning that whole string as `doctor` made the
// agent read the service suffix out loud, and pass it back into booking. Split it: `doctor` is the
// speakable name, `service` is the suffix, and the name matcher resolves either form to the same
// single calendar (verified against all 30 live names).
const splitName = raw => {
  const s = (raw || '').toString().replace(/\s+/g, ' ').trim();
  const m = s.match(/^(.*?)\s+[-\u2013\u2014]\s+(.*)$/);
  // No `service` key at all when there is no suffix, so 29 of 30 calendars are unchanged.
  return m ? { doctor: m[1].trim(), service: m[2].trim() } : { doctor: s };
};
const q = $('CA Validate Input').first().json;
const resp = $input.first().json;
if (resp.statusCode !== 200 || !resp.body || !resp.body.Calendars) {
  return [{ json: { _error: true, success: false, error: 'evolvo_api_error', step: 'get_info',
    status: resp.statusCode } }];
}
const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const STOP = ['dr','dra','doktor','doctor','doamna','domnul','doctorul','doctorita','medic','medicul','doktornő','doktorno','doktor ur','ur','urnő','urno'];
const words = s => norm(s).split(/[^a-z0-9]+/).filter(w => w && !STOP.includes(w));
const lev = (a, b) => { const m = a.length, n = b.length; if (!m) return n; if (!n) return m;
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) { const cur = [i];
    for (let j = 1; j <= n; j++) cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    prev = cur; }
  return prev[n]; };
// A spoken/ASR name token matches a calendar name token when equal, a prefix (>=3 chars), or within a small edit distance.
const tokEq = (q, t) => q === t || (q.length >= 3 && (t.startsWith(q) || q.startsWith(t))) || (q.length >= 3 && lev(q, t) <= (q.length >= 5 ? 2 : 1));
const nameMatch = (query, name) => { const qw = words(query), nw = words(name); return qw.length > 0 && qw.every(q => nw.some(t => tokEq(q, t))); };
// Provider kind, read off the calendar name as evolvo writes it.
// "Optometrist Bodi Ildiko" -> optometrist. "Dr. Baricz Anna" -> doctor.
// A name carrying a service suffix is a SPECIALTY calendar, not general eye care:
// "Dr. Prof. Szekely Attila  - Consiliere / Terapie psiho-ortoptica" -> vision_therapy.
// Anything unrecognised is treated as a doctor: the safe direction to fail in.
const providerKind = name => {
  const n = norm(name).trim();
