  if (requestedDay) res.requested_date_slots = requestedDay;
}
res.note = 'Times are local Romania time (24h). earliest = the single earliest free slot across all matched calendars; use it for urgent callers or callers with no preference. The system searched the next ~15 working days of each calendar starting from date_searched_from, so nothing here falls before that date and nothing here is today. ' + SPEAK_DATES;
return [{ json: res }];

const b = ($input.first().json.body) || {};
const str = x => (typeof x === 'string' ? x.trim() : '');
const missing = [];
const full_name = str(b.full_name);
const PLACEHOLDER = ['necunoscut','ismeretlen','unknown','n/a','na','-','pacient','patient','beteg'];
if (!full_name || full_name.replace(/[^\p{L}]/gu, '').length < 2 || PLACEHOLDER.includes(full_name.toLowerCase())) missing.push('full_name (real full name, never empty or a placeholder)');
const phone = str(b.phone).replace(/[\s\-\.]/g, ''); if (!phone) missing.push('phone');
