  const now = Date.now();
  for (const k of Object.keys(sd.phoneGate)) if (now - sd.phoneGate[k] > 2 * 3600 * 1000) delete sd.phoneGate[k];
  const conv = conversation_id || 'anon';
  const gateKey = conv + '|' + phone;
  const confirmed = b.phone_confirmed === true || String(b.phone_confirmed).toLowerCase() === 'true';
  const firstRefusal = sd.phoneGate[gateKey];
  if (!confirmed || (firstRefusal && now - firstRefusal < 5000)) {
    if (!firstRefusal) sd.phoneGate[gateKey] = now;
    const d = phone.split('');
    const groups = [];
    for (let i = 0; i < d.length; i += 3) groups.push(d.slice(i, i + 3).join(', '));
    return [{ json: { _error: true, success: false, error: 'confirm_phone_first', phone,
      read_back: groups.join(' — '),
      message: 'Nothing was done yet. First read this phone number back to the caller digit by digit, ask whether it is correct, and END your turn. Only after the caller answers yes, call this tool again with exactly the same details and phone_confirmed set to true. If the caller corrects the number, call again with the corrected number and phone_confirmed true after they confirm it.' } }];
  }
  if (conversation_id) sdp.confirmedPhone[conversation_id] = { phone, ts: Date.now() };
}
// idempotency: one log per conversation id, remembered for 6 hours
const sd = $getWorkflowStaticData('global'); sd.logKeys = sd.logKeys || {};
const now = Date.now();
for (const k of Object.keys(sd.logKeys)) if (now - sd.logKeys[k] > 6 * 3600 * 1000) delete sd.logKeys[k];
if (conversation_id && sd.logKeys[conversation_id]) {
  return [{ json: { _error: true, success: true, duplicate: true,
    message: 'This request was already logged during this call; a colleague will call back.' } }];
}
if (conversation_id) sd.logKeys[conversation_id] = now;
const timestamp = new Date().toLocaleString('sv-SE', { timeZone: 'Europe/Bucharest' });
return [{ json: { timestamp, request_type, patient_name, phone, branch, summary, language, conversation_id,
  status: 'new', source: 'voice_agent', phone_recovered } }];

const q = $('LOG Validate Input').first().json;
const r = $input.first().json;
if (r && r.error && !r.timestamp) {
  return [{ json: { success: false, error: 'log_failed', detail: String(r.error).slice(0, 200),
    hint: 'Tell the caller a colleague will call back, and give them the branch direct number from the knowledge base.' } }];
}
return [{ json: { success: true, logged: true, request_type: q.request_type, branch: q.branch || null,
  routed_to: 'callback_sheet',
  message: 'Request logged for the clinic team; a colleague will call the patient back. Do not promise a specific time or person, and do not give a reference number.' } }];

// Final BOOK response. Strips the internal reschedule hand-off fields and, when an old appointment
// had to be cancelled to free its slot, reports whether that cancellation actually went through.
const base = { ...$('BOOK Format Booking').first().json };
const sid = base._resched_scheduleid || '';
const old = base._resched_old || null;
delete base._resched_scheduleid; delete base._resched_old; delete base._resched_obs;
if (!sid || !old) return [{ json: base }];
const r = $input.first().json || {};
const ok = r.statusCode === 200 && r.body && r.body.Result === 'OK';
const when = (old.date_spoken || old.date || '') + ' ' + (old.time || '');
base.replaced_appointment = { ref: old.ref, person: old.person, date: old.date,
  date_spoken: old.date_spoken || '', time: old.time,
  doctor: old.doctor, location: old.location, cancelled: !!ok };
base.note = ok
  ? base.note + ' The earlier appointment (' + when + ') has been cancelled and its slot released.'
  : base.note + ' IMPORTANT: the new time is booked, but the earlier appointment (' + when + ') could NOT be cancelled - tell the caller the clinic will remove the old one.';
return [{ json: base }];

// Reuse the 31-day scan FIND already did in this same call (2026-09-14).
// FIND and MAN otherwise run the identical 6 evolvo calls for the same phone, seconds apart. On a
// hit we skip get_schedule_patient.php AND the five get_schedule.php windows entirely.
// Evolvo stays the source of truth: the TTL is short, the entry is dropped the moment MAN changes
// anything, and update_schedule.php still validates the scheduleid we send.
const prev = $input.first().json;
if (prev._error) return [{ json: prev }];
const q = $('MAN Validate Input').first().json;
const digits = p => { let d = (p || '').toString().replace(/\D/g, ''); if (d.startsWith('0040')) d = d.slice(4); else if (d.startsWith('40') && d.length > 10) d = d.slice(2); return d.replace(/^0+/, ''); };
const sd = $getWorkflowStaticData('global'); sd.scanCache = sd.scanCache || {};
const now = Date.now();
for (const k of Object.keys(sd.scanCache)) if (now - sd.scanCache[k].ts > 180000) delete sd.scanCache[k];
const conv = q.conversation_id;
const key = (conv && conv !== 'anon') ? conv + '|' + digits(q.phone) : null;
const hit = key ? sd.scanCache[key] : null;
return [{ json: { ...prev, _cache_key: key, _cache_hit: Boolean(hit), _cached_recs: hit ? hit.recs : [] } }];

// Match the cancelled appointment's provider+branch to a calendarid so we can ask evolvo whether the
// slot is genuinely free again, rather than telling the caller it is and hoping (2026-09-14).
const upd = $('MAN Format Update').first().json;
const a = upd.appointment || {};
const r = $input.first().json;
const norm = s => (s || '').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
const cals = (r.statusCode === 200 && r.body && r.body.Calendars) ? r.body.Calendars : [];
const match = cals.find(c => norm(c.name || c.doctor_name) === norm(a.doctor) && norm(c.workstation) === norm(a.location));
// date_from must be a future date for evolvo; a same-day or past appointment cannot be re-checked.
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Bucharest' });
if (!match || !a.date || a.date <= today) {
  return [{ json: { _skip: true, reason: !match ? 'calendar_not_matched' : 'date_not_future' } }];
}
return [{ json: { _skip: false, calendarid: match.calendarid, date_from: a.date, want_date: a.date, want_time: a.time } }];

// Final MAN response. Reports whether the cancelled slot actually came back, as a field the agent can
// read instead of an assumption it has to make (2026-09-14, asked for by the ElevenLabs side).
const base = { ...$('MAN Format Update').first().json };
const wanted = base._check_release;
delete base._check_release;
if (!wanted) return [{ json: base }];

let status = 'unknown', freeTimes = null, skip = null;
try { const s = $('MAN rel Find Calendar').first().json; if (s && s._skip) skip = s.reason; } catch (e) { skip = 'not_checked'; }
if (!skip) {
  try {
    const s = $('MAN rel Find Calendar').first().json;
    const r = $input.first().json;
    if (r.statusCode === 200 && r.body && Array.isArray(r.body.Records)) {
      const day = r.body.Records.find(d => (d.wday || '').slice(0, 10) === s.want_date);
      freeTimes = day ? (day.free_timespace || []).map(x => (x.slot || '').slice(0, 5)) : [];
      if (freeTimes.includes(s.want_time)) status = 'released';
      else if (freeTimes.length) status = 'still_blocked';
      else status = 'unknown';   // the whole day is gone from the calendar - fully booked, or not a working day
    } else status = 'check_failed';
  } catch (e) { status = 'check_failed'; }
} else {
  status = skip === 'date_not_future' ? 'not_checkable_same_day' : 'check_failed';
}

base.slot_released = status === 'released';
base.slot_release_status = status;
const a = base.appointment || {};
const when = (a.date_spoken || a.date || '') + ' ' + (a.time || '');
if (status === 'released') {
  base.note = 'Cancelled, and the ' + when + ' slot is free again - it can be booked straight away.';
} else if (status === 'still_blocked') {
  base.note = 'Cancelled. The ' + when + ' slot has NOT reappeared yet, so do not tell the caller that time is available again; offer to look for another time.';
} else {
  base.note = 'Cancelled. We could not verify whether the ' + when + ' slot reopened, so do not claim it is bookable again.';
}
return [{ json: base }];
